import type {
  CodeGenerationMetricCardsPayload,
  MultiColumnChartPayload,
} from '@github-ui/copilot-insights-shared/types/chart-types'
import {copilotInsightsCodeGenerationAppBuilder} from '../config/app-builder'
import {mainQuery} from '@github-ui/react-core/future/main-query'

export type CopilotCodeGenerationRouteResponse = {
  codeGenerationMetrics: {
    metricCardsData: CodeGenerationMetricCardsPayload
    dailyTotalLinesOfCode: MultiColumnChartPayload
    userInitiatedCodeChanges: MultiColumnChartPayload
    agentInitiatedCodeChanges: MultiColumnChartPayload
    agentInitiatedCodeChangesPerModel: MultiColumnChartPayload
    userInitiatedCodeChangesPerLanguage: MultiColumnChartPayload
    agentInitiatedCodeChangesPerLanguage: MultiColumnChartPayload
    userInitiatedCodeChangesPerModel: MultiColumnChartPayload
  }
  slug: string
  copilotLicenseManagementLink: string
  aiControlsLink: string
  displayBlankslate: boolean
  displayError: boolean
  displayNoMatchingResults?: boolean
  displayCodeGenerationDisclaimer: boolean
  exportFilesUrl: string
  businessId?: number
  orgId?: number
  canonicalQueryParams: {
    period: string
    interval: string
  }
  insightsOptedIn: boolean
  canManageAiControls: boolean
  copilotDisabled: boolean
  canManageCopilotLicenses?: boolean
  importedDataFilename?: string
  sidenav?: {
    selectedKey: string
    showDependencies: boolean
    showActionsUsageMetrics: boolean
    showApi: boolean
    showCopilotUsage: boolean
    showCopilotCodeGeneration: boolean
    urls: Record<string, string>
  }
}

// stafftools version of the route
export const stafftoolsCopilotCodeGenerationRoute = copilotInsightsCodeGenerationAppBuilder.createQueryRouteConfig(
  'stafftoolsCopilotCodeGenerationRoute',
  {
    path: '/stafftools/enterprises/:slug/copilot_insights_code_generation',
    queries: [
      mainQuery<CopilotCodeGenerationRouteResponse>({
        queryDeps: ({pathname, searchParams}) => ({
          pathname,
          searchParams: {
            period: searchParams.get('period') || '28d',
          },
        }),
      }),
    ],
  },
)

