import DataCard from '@github-ui/data-card'
import {Stack, Link} from '@primer/react'
import type {ReactNode} from 'react'
import styles from '../../styles/MetricCard.module.css'

type MetricCardProps = {
  title: string
  value: ReactNode
  description: string
  linkLabel?: string
  linkUrl?: string
  children?: ReactNode
}

export function MetricCard({title, value, description, linkLabel, linkUrl, children}: MetricCardProps) {
  return (
    <DataCard className="width-full height-full">
      <Stack direction="vertical" gap="condensed">
        <Stack direction="horizontal" justify="space-between" align="end">
          <h2 className="f5 mb-0">{title}</h2>
          {linkUrl && linkLabel && (
            <Link className={`f6 text-right ${styles.linkedText}`} inline href={linkUrl}>
              {linkLabel}
            </Link>
          )}
        </Stack>
        <span className="f2 my-0">{value}</span>
        {children}
        <DataCard.Description className="mt-0">{description}</DataCard.Description>
      </Stack>
    </DataCard>
  )
}
